function events(){for(const ev of game.events.splice(0)){
  if(['companion','hired','dismissed','expired','down','revived','order','stance'].includes(ev.type)){companionHud?.update();updateCompanionPanel(popups.get('companions')?.body,game);}
  if(ev.type==='instanceChanged'){popups.closeAll();mobile?.stop();renderer.camera={...game.player};document.body.dataset.instance=game.instance?.id||'';}
  if(ev.type==='levelUp'){/* Lichtsäule am Helden (renderer.js drawLevelUp) */game.effect?.('levelup',game.player.x,game.player.y,{life:1.8,max:1.8,radius:70});const skills=[];pendingLevel={level:ev.level,hpGain:ev.hpGain,points:pointsAtLevel(ev.level)-pointsAtLevel(ev.level-1),skills};queueMicrotask(()=>{if(pendingLevel){milestones?milestones.level(pendingLevel):toast(ev.text);pendingLevel=null;}});}if(ev.type==='tutorialStep')tutorialUI?.update();if(ev.type==='activity')showActivity();if(ev.type==='rpgChanged'){equipFlash();syncPreviewArt();buildActions();refreshPanels();paintPortrait();}if(ev.type==='skillsUnlocked'){buildActions();refreshPanels();if(pendingLevel)for(const id of ev.ids||[]){const s=game.skills.find(k=>k.id===id);if(s)pendingLevel.skills.push(s.name);}if(!pendingLevel)toast('Neuer Kniff gelernt. Erklärung im Skillbuch [K].');}if(ev.type==='classChanged'){syncPreviewArt();buildActions();refreshPanels();paintPortrait();toast(game.member.name+' ist am Start.');}if(ev.type==='toast')toast(ev.text,ev.error);if(ev.type==='targetState')cues.flashState();if(ev.type==='autopilotStop')cues.attacked();if(ev.type==='settingsChanged'){syncPreviewArt();if(combatText)combatText.enabled=game.settings.sct!==false;if(fpsMeter)fpsMeter.enabled=game.settings.fps===true;if(ev.key==='fullRes'||ev.key==='autoRes'||ev.key==='lowRes')renderer.resize();}if(ev.type==='save')save();if(ev.type==='sound')sound(ev.id);if(ev.type==='target')sound('target');if(ev.type==='shake')renderer.shake=ev.strength;
  if(ev.type==='attacked'){sawAttackEvent=true;warnAttacked(ev.name);cues.attacked();}
  if(ev.type==='loot'){lootLine(ev);renderer?.lootFly?.(ev);};
  if(ev.type==='barChanged'){buildActions();if(popups.isOpen('book'))showBook();}
  if(ev.type==='settingsChanged'&&popups.isOpen('settings'))showSettings();
  if(ev.type==='bark')renderer?.bossSpeech.bark(ev,game);if(ev.type==='combat'){combatText?.push(ev);/* Eigener Glückstreffer: kurzer Kamerastoß (Hades/Diablo), sanft und nur ohne reduzierte Bewegung */if(ev.crit&&ev.area==='out'&&!ev.actor&&renderer&&!matchMedia?.('(prefers-reduced-motion: reduce)').matches)renderer.shake=Math.max(renderer.shake||0,2.2);}
  if(ev.type==='discovery')toast(ev.name+' entdeckt · +20 EP');
  if(ev.type==='revived'&&popups.isOpen('death'))closeModal();
  if(ev.type==='death')openModal(`<span class="eyebrow">DER ABEND IST NOCH NICHT VORBEI</span><h2>Du wurdest fachgerecht zusammengefaltet.</h2><p>Du wurdest besiegt. Achte auf die Zauberbalken: ${available(game,'interrupt')?'Gelbe Zauber mit <kbd>'+keyFor(game,'interrupt')+'</kbd> unterbrechen.':'Bei Fernangriffen Abstand vergrößern oder die Sichtlinie unterbrechen.'} Rote Flächen verlassen oder mit <kbd>${keyFor(game,'dash')}</kbd> ausweichen. ${available(game,'parry')?'Angekündigte Nahkampfhiebe lassen sich mit <kbd>'+keyFor(game,'parry')+'</kbd> parieren.':'Deine weiteren Verteidigungsfähigkeiten lernst du nach und nach.'} Deine Quest und Erfahrung bleiben erhalten.</p><div class="dialog-actions"><button class="gold-button" id="respawn">Am Treffpunkt zusammenkratzen lassen</button></div>`,false,'death');
  if(ev.type==='bossVictory'&&BOSS_LINES[ev.boss])toast('„'+BOSS_LINES[ev.boss].defeat+'“');
  // Death memories remain saved in Aufträge → Erinnerungen; the existing toast announces them without another modal.
  if(ev.type==='memory'&&!game.dead){memoryQueue.push(ev.fragment);showMemory();}
  if(ev.type==='mentorTalk')openModal(mentorDialogue(ev),false,'dialog');
  if(ev.type==='buildingsChanged'&&popups.isOpen('quest'))showJournal();
  if(ev.type==='chapterChanged'){popups.close('dialog');lastQuestState='';if(popups.isOpen('quest'))showJournal();updateUI();renderer.map($('#minimap'));}
}}
function frame(now){const started=performance.now();/* eigene Rechenzeit ab hier – der rAF-Zeitstempel `now` liegt davor (Bildbeginn), die Wartezeit gehört nicht dazu */professionsUI?.poll();if(game&&popups.isOpen('trainer')){const t=professionRoute(game,'teacher:'+trainerId);if(!t||distance(t,game.player)>PROFESSION_RULES.range+30||game.instance)popups.close('trainer');}if(game&&now-lastUI>100)refreshProfessionWindows();if(game&&popups.isOpen('shop')){const reason=shopUnavailable(game);if(reason){popups.close('shop');toast(SHOP_UI.closeReason+reason);}}const gap=now-last,dt=Math.min(gap/1000,.05);last=now;game.tick(dt);{const t=arrivedToTalk(game);if(t)talkWith(t);}if(popups.isOpen('loot')){const bag=game.rpg.loot.find(b=>b.id===selectedLootId);if(!bag||game.dead||distance(bag,game.player)>=COMBAT_RULES.lootRange)popups.close('loot');}events();renderer.draw();combatText?.update(renderer,game);if(now-lastUI>100){updateUI();lastUI=now;}if(now-lastMap>200){renderer.map($('#minimap'));if(popups.isOpen('map'))refreshMapPanel();lastMap=now;}toasts.tick(now);if(!startScreen?.isOpen){/* Anmeldebildschirm und Laden zählen nicht als Spieltempo */const work=performance.now()-started;renderer.pace(gap,work);renderer.idle();}fpsMeter?.frame(now,performance.now()-started,[renderer.software?'ohne Grafikkarte':'',renderer.gradeOff&&!renderer.software?'ohne Farbfilter':'',renderer.densityCap!=null?'Auflösung '+renderer.density+'/'+worldDensity(renderer.zoom,false):'',game.settings.fx!==false&&renderer.fx?.stats?'Effekte '+renderer.fx.stats.mode:''].filter(Boolean).join(' · '));requestAnimationFrame(frame);}
