modal.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const d=b.dataset;let handled=true;if(d.mountAcquire)game.acquireMount(d.mountAcquire);else if('ridingSkill' in d)game.learnRiding();else if(d.mountSelect)game.selectMount(d.mountSelect);else if(d.mountRide){if(game.player.mount===d.mountRide||game.mountCast?.id===d.mountRide)game.dismount();else{game.dismount();game.selectMount(d.mountRide);if(game.toggleMount())popups.close('mounts');}}else if('mountTravel' in d){game.navigate(mountStation(world));popups.close('mounts');}else if('mountTurn' in d){const dirs=['se','sw','nw','ne'];mountDirection=dirs[(dirs.indexOf(mountDirection)+1)%4];}else if('mountBind' in d){openModal('<h2>'+MOUNT_UI.slot+'</h2><div class="bar-picker">'+game.bar().map(s=>'<button class="outline-button" data-mount-slot="'+s.index+'"><kbd>'+s.key+'</kbd> '+(s.name||'—')+'</button>').join('')+'</div>',false,'detail');}else if(d.mountSlot!==undefined){bindSkill(game,'mount',Number(d.mountSlot));popups.close('detail');buildActions();}else handled=false;if(handled){events();updateMountPanel(popups.get('mounts')?.body,game,mountDirection);}});

function professionLock(on,text=PROFESSION_UI.pending,retry){let el=document.querySelector('.profession-save-lock');if(!el){el=document.createElement('div');el.className='profession-save-lock';el.setAttribute('role','alertdialog');document.body.append(el);}el.hidden=!on;el.replaceChildren();if(on){const p=document.createElement('p');p.textContent=text;el.append(p);if(retry){const b=document.createElement('button');b.textContent=PROFESSION_UI.retry;b.onclick=retry;el.append(b);b.focus();}}}
for(const type of ['pointerdown','click','contextmenu','keydown'])window.addEventListener(type,e=>{if(game?.professionCommit&&!e.target.closest('.profession-save-lock')){e.preventDefault();e.stopImmediatePropagation();}},true);
