modal.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const d=b.dataset,v=professionView;if(d.profTab){v.tab=d.profTab;v.confirm=null;}else if(d.profRecipe)v.recipe=d.profRecipe;else if(d.profConfirm!==undefined)v.confirm=d.profConfirm||null;else if(d.profLearn)professionsUI.start({kind:'learn',target:d.profLearn});else if(d.profTrain)professionsUI.start({kind:'train',target:d.profTrain});else if(d.profForget){v.confirm=null;professionsUI.start({kind:'forget',target:d.profForget});}else if(d.profCraft)professionsUI.start({kind:'craft',target:d.profCraft});else if(d.profRoute){const p=professionRoute(game,d.profRoute);if(p){cancelProfession(game);game.navigate(p);popups.close(b.closest('.game-popup')?.dataset.window);}return;}else return;refreshProfessionWindows();});
